mapper.select:
SELECT u.id, u.username, u.real_name, u.phone, u.email, u.avatar, u.role_type, u.status, u.last_login_time, u.create_time FROM t_user u WHERE u.deleted_flag = 0
AND (u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND u.role_type = #{query.roleType}
AND u.status = #{query.status}
ORDER BY u.create_time DESC
